const holes=[[0,0],[500,0],[1000,0],[0,500],[500,500],[1000,500]];
export function poolStart(){const cells=Array(29).fill(0);cells[0]=2500;cells[1]=2500;cells[2]=1;let n=1;for(let col=0;col<4&&n<9;col++)for(let row=0;row<=col&&n<9;row++,n++){cells[n*3]=6500+col*215;cells[n*3+1]=2500+Math.round((row-col*.5)*250);cells[n*3+2]=1;}return{game:'pool',cells,turn:1,winner:0,over:false,moves:0,fen:'',history:[]};}
export function poolMove(s,actor,command){if(s.over||s.turn!==actor)throw Error('turn');const spinCode=Math.floor(command/363600),shot=command%363600,power=Math.floor(shot/3600),angle=shot%3600;if(!Number.isInteger(command)||command<0||spinCode>8||power<1||power>100)throw Error('shot');const side=[0,0,Math.SQRT1_2,1,Math.SQRT1_2,0,-Math.SQRT1_2,-1,-Math.SQRT1_2][spinCode],follow=[0,1,Math.SQRT1_2,0,-Math.SQRT1_2,-1,-Math.SQRT1_2,0,Math.SQRT1_2][spinCode],ax=Math.cos(angle*Math.PI/1800),ay=Math.sin(angle*Math.PI/1800);let spinLife=1,contactSpin=false;const c=s.cells.slice(),x=[],y=[],vx=Array(9).fill(0),vy=Array(9).fill(0),alive=[];for(let i=0;i<9;i++){x[i]=c[i*3]/10;y[i]=c[i*3+1]/10;alive[i]=c[i*3+2]===1;}vx[0]=Math.cos(angle*Math.PI/1800)*power*.16;vy[0]=Math.sin(angle*Math.PI/1800)*power*.16;const history=[],frame=()=>x.flatMap((v,i)=>[Math.round(v*10),Math.round(y[i]*10),alive[i]?1:0]).join(',');let pocket=0,scratch=false,black=false;
 for(let step=0;step<1200;step++){let speed=0;for(let i=0;i<9;i++)if(alive[i]){x[i]+=vx[i];y[i]+=vy[i];if(holes.some(h=>Math.hypot(x[i]-h[0],y[i]-h[1])<27)){alive[i]=false;vx[i]=vy[i]=0;if(i===0)scratch=true;else if(i===8)black=true;else pocket++;continue;}if(x[i]<12||x[i]>988){x[i]=Math.max(12,Math.min(988,x[i]));vx[i]*=-.92;if(i===0&&side){const speed=Math.hypot(vx[i],vy[i]);vy[i]+=Math.abs(vx[i])*side*.18*spinLife;const scale=speed/Math.hypot(vx[i],vy[i]);vx[i]*=scale;vy[i]*=scale;}}if(y[i]<12||y[i]>488){y[i]=Math.max(12,Math.min(488,y[i]));vy[i]*=-.92;if(i===0&&side){const speed=Math.hypot(vx[i],vy[i]);vx[i]-=Math.abs(vy[i])*side*.18*spinLife;const scale=speed/Math.hypot(vx[i],vy[i]);vx[i]*=scale;vy[i]*=scale;}}vx[i]*=.985;vy[i]*=.985;if(Math.hypot(vx[i],vy[i])<.035)vx[i]=vy[i]=0;speed+=Math.hypot(vx[i],vy[i]);}
 for(let i=0;i<9;i++)for(let j=i+1;j<9;j++)if(alive[i]&&alive[j]){const dx=x[j]-x[i],dy=y[j]-y[i],d=Math.hypot(dx,dy);if(d>0&&d<24){const nx=dx/d,ny=dy/d,overlap=(24-d)/2;x[i]-=nx*overlap;y[i]-=ny*overlap;x[j]+=nx*overlap;y[j]+=ny*overlap;const impulse=(vx[i]-vx[j])*nx+(vy[i]-vy[j])*ny;if(impulse>0){vx[i]-=impulse*nx;vy[i]-=impulse*ny;vx[j]+=impulse*nx;vy[j]+=impulse*ny;if(i===0&&!contactSpin&&spinCode){const forward=power*.035*follow*spinLife,lateral=power*.018*side*spinLife;vx[0]+=ax*forward-ay*lateral;vy[0]+=ay*forward+ax*lateral;contactSpin=true;}}}}spinLife*=.997;if(step%25===0&&history.length<48)history.push(frame());if(speed<.04&&step>1)break;}
 if(scratch){alive[0]=true;outer:for(let xx=180;xx<=420;xx+=30)for(let yy=80;yy<450;yy+=30){if(x.every((v,i)=>i===0||!alive[i]||Math.hypot(xx-v,yy-y[i])>=27)){x[0]=xx;y[0]=yy;break outer;}}}for(let i=0;i<9;i++){c[i*3]=Math.round(x[i]*10);c[i*3+1]=Math.round(y[i]*10);c[i*3+2]=alive[i]?1:0;}c[26+actor]+=pocket;const remaining=alive.slice(1,8).some(Boolean),over=black||s.moves+1>=200,winner=black?(scratch||remaining?3-actor:actor):over?(c[27]===c[28]?0:c[27]>c[28]?1:2):0;history.push(frame());return{game:'pool',cells:c,turn:pocket&&!scratch?actor:3-actor,winner,over,moves:s.moves+1,fen:scratch?'白球落袋，换手并复位':black?'8号球落袋':'本杆落袋 '+pocket+' 颗',history};}
export function poolBot(s){const c=s.cells;let target=8,best=Infinity;for(let i=1;i<8;i++)if(c[i*3+2]===1){const d=Math.hypot(c[i*3]-c[0],c[i*3+1]-c[1]);if(d<best){target=i;best=d;}}const a=(Math.round(Math.atan2(c[target*3+1]-c[1],c[target*3]-c[0])*1800/Math.PI)+3600)%3600;return 75*3600+a;}
